    }

    function exploitAddLPRatio() internal pure returns (uint256) {
        return ADD_LP_RATIO;
    }

    function precision() internal pure returns (uint256) {
        return PRECISION;
    }

    function pipeline() internal pure returns (IPipeline) {
        return IPipeline(PIPELINE);
    }
}

